mapper.update:
UPDATE system_org SET ancestors = CONCAT(#{newAncestorPrefix}, SUBSTRING(ancestors, LENGTH(#{oldAncestorPrefix})+1)) WHERE id IN
#{id}
AND ancestors LIKE CONCAT(#{oldAncestorPrefix}, '%') AND deleted = 0

mapper.select:
SELECT ou.user_id AS userId, GROUP_CONCAT(o.name) AS orgNames FROM system_org_user ou JOIN system_org o ON ou.org_id = o.id and o.deleted = b'0' and ou.deleted = b'0' WHERE ou.user_id IN
#{id}
GROUP BY ou.user_id
